    font-family: inherit;
}

.modal-input:focus {
    outline: none;
    border-color: #558255;
    box-shadow: 0 0 0 4px rgba(85, 130, 85, 0.1);
}

.modal-input::placeholder {
    color: #9ca3af;
}

.error_namemodal {
    display: none;
